.container {
  display: flex;
  flex-direction: column;
  justify-content: center;
  height: 32px;
  margin-inline: 2px;
  padding-block: 2px;
  padding-inline: 6px;
  position: relative;
}
.root {
  --discrete-duration: 0.3s;
  --discrete-easing: cubic-bezier(0.23, 1, 0.32, 1);
  display: flex;
  align-items: center;
  width: 100%;
  height: 28px;
  padding: 0;
  position: relative;
  touch-action: none;
}
.root[data-disabled] {
  opacity: 0.6;
}
.root[data-disabled] .tick {
  cursor: default;
  pointer-events: none;
}
.root[data-locked="true"] .track {
  background-image: repeating-linear-gradient(
    135deg,
    var(--ck-palette-border) 0,
    var(--ck-palette-border) calc(var(--spacing) / 4),
    transparent calc(var(--spacing) / 4),
    transparent var(--spacing)
  );
}
.root[data-locked="true"] .tick[data-locked="true"] {
  background-color: currentColor;
}
.root[data-dragging="true"] {
  --discrete-duration: 0.15s;
  cursor: grabbing;
}
.root[data-dragging="true"] .thumbInput,
.root[data-dragging="true"] .tick {
  cursor: grabbing;
}
.track {
  clip-path: var(--discrete-track-clip);
  background: color-mix(in srgb, var(--ck-palette-ink) 10%, transparent);
  height: 24px;
  box-shadow: inset 0 0 0 0.5px var(--ck-palette-border);
  border-radius: 12px;
  flex-grow: 1;
  position: relative;
  overflow: hidden;
}
.range {
  background: var(--ck-palette-accent-blue);
  border-radius: 12px 0 0 12px;
  width: 100%;
  height: 100%;
  position: absolute;
  inset-inline-start: 0;
  clip-path: inset(
    0 calc(100% - var(--discrete-position) - 14px) 0 0 round 9999px
  );
  transition: clip-path var(--discrete-duration) var(--discrete-easing);
}
.tickRail {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.tick {
  width: 4px;
  height: 4px;
  cursor: default;
  pointer-events: auto;
  background: currentColor;
  border-radius: 50%;
  position: absolute;
  top: 50%;
  left: var(--discrete-position);
  transform: translate(-50%, -50%);
  transition:
    background-color var(--discrete-duration) var(--discrete-easing),
    transform 0.12s ease;
}
.tick::before {
  content: "";
  position: absolute;
  inset: -6px;
}
.tick[data-selected="true"] {
  color: color-mix(in srgb, var(--ck-fixed-white) 30%, transparent);
}
.tick[data-selected="false"] {
  color: color-mix(in srgb, var(--ck-palette-ink-tertiary) 50%, transparent);
}
.tick[data-locked="true"] {
  background: transparent;
}
.tick[data-locked="true"] svg {
  width: 12px;
  height: 12px;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}
.visualThumbRail {
  width: 100%;
  position: absolute;
  inset-block: 0;
  left: 0;
  pointer-events: none;
  z-index: 4;
}
.thumbScale {
  width: 28px;
  height: 28px;
  position: absolute;
  top: 50%;
  left: var(--discrete-position);
  transform: translate(-50%, -50%);
  transition: left var(--discrete-duration) var(--discrete-easing);
}
.thumb {
  display: flex;
  align-items: center;
  justify-content: center;
  border: 0.5px solid var(--ck-palette-border-heavy);
  color: var(--ck-palette-ink);
  background: white;
  border-radius: 50%;
  position: absolute;
  inset: 0;
  box-shadow: var(--shadow-subtle);
}
.root > span:has(> .thumbInput) {
  left: var(--discrete-position);
}

.thumbInput {
  box-sizing: border-box;
  width: 28px;
  height: 28px;
  cursor: default;
  border-radius: 50%;
  background: transparent;
  outline: 0;
  box-shadow: none;
  display: block;
  position: relative;
}
.thumbInput::before {
  content: "";
  position: absolute;
  inset: -3px;
  border-radius: 50%;
}
.explicitOption {
  cursor: default;
  background: transparent;
  border: 0;
  padding: 0;
}
.explicitOption[data-selected="true"] {
  visibility: hidden;
}
.container[data-ck-keyboard-focused="true"] .visualThumbRail .thumb {
  outline: 2px solid var(--ck-palette-border-focus);
  outline-offset: 0;
}
@media (hover: hover) {
  .root:not([data-dragging="true"]) .tick:not([data-locked="true"]):hover {
    filter: brightness(0.85);
    transform: translate(-50%, -50%) scale(2);
  }
}
@media (prefers-reduced-motion: reduce) {
  .root,
  .root[data-dragging="true"] {
    --discrete-duration: 0s;
  }
  .tick {
    transition: none;
  }
}

"use client";

import { NamedIcon } from "@/components/icon/registry";
import { SliderRoot, SliderThumb } from "@/components/ui/slider";
import { cn } from "@/lib/utils";
import { useState } from "react";
import type { CSSProperties, ReactNode } from "react";

import styles from "./discrete-slider.module.css";

interface DiscreteSliderOption {
  id: string;
  label: string;
  icon?: ReactNode;
  isLocked?: boolean;
  requiresExplicitSelection?: boolean;
}

interface DiscreteSliderProps {
  "aria-label": string;
  className?: string;
  disabled?: boolean;
  options: readonly DiscreteSliderOption[];
  selectedOptionId: string;
  onSelectOption: (option: DiscreteSliderOption) => void;
}

type SliderStyle = CSSProperties & Record<`--${string}`, string>;

const position = (index: number, lastIndex: number) => {
  const percentage = (index / lastIndex) * 100;

  return `calc(${percentage}% + ${13 - (percentage / 50) * 13}px)`;
};

function DiscreteSlider({
  "aria-label": ariaLabel,
  className,
  disabled = false,
  options,
  selectedOptionId,
  onSelectOption,
}: DiscreteSliderProps) {
  const [dragging, setDragging] = useState(false);
  const [keyboardFocused, setKeyboardFocused] = useState(false);

  const explicitIndex = options.findIndex(
    (option) => option.requiresExplicitSelection === true
  );

  const ordinaryCount = explicitIndex === -1 ? options.length : explicitIndex;

  if (
    ordinaryCount === 0 ||
    options
      .slice(ordinaryCount)
      .some((option) => option.requiresExplicitSelection !== true)
  ) {
    throw new Error(
      "Place options requiring confirmation after the directly selectable slider options."
    );
  }

  const selectedIndex = Math.max(
    0,
    options.findIndex((option) => option.id === selectedOptionId)
  );

  const selected = options[selectedIndex];
  const lastIndex = Math.max(1, options.length - 1);

  const selectedStyle: SliderStyle = {
    "--discrete-position": position(selectedIndex, lastIndex),
  };

  const trackStyle: SliderStyle = {
    "--discrete-track-clip":
      explicitIndex === -1
        ? "none"
        : `inset(0 calc(100% - ${position(Math.max(ordinaryCount - 1, selectedIndex), lastIndex)} - 14px) 0 0 round 9999px)`,
  };

  const select = (index: number) => {
    const option = options[index];

    if (!disabled && option !== undefined) {
      onSelectOption(option);
    }
  };

  return (
    <div
      className={cn(styles.container, className)}
      data-ck-keyboard-focused={keyboardFocused}
    >
      <SliderRoot
        className={styles.root}
        data-dragging={dragging}
        data-locked={
          disabled && options.some((option) => option.isLocked === true)
        }
        dir="ltr"
        disabled={disabled || options.length <= 1}
        max={lastIndex}
        style={selectedStyle}
        onBlur={() => {
          setKeyboardFocused(false);
        }}
        onFocus={(event) => {
          setKeyboardFocused(event.target.matches(":focus-visible"));
        }}
        onKeyDown={() => {
          setKeyboardFocused(true);
        }}
        onLostPointerCapture={() => {
          setDragging(false);
        }}
        onPointerCancel={() => {
          setDragging(false);
        }}
        onPointerDown={() => {
          setKeyboardFocused(false);
        }}
        onPointerMove={(event) => {
          if (!disabled && event.buttons !== 0) {
            setDragging(true);
          }
        }}
        onPointerUp={() => {
          setDragging(false);
        }}
        onValueChange={(values) => {
          select(
            Math.min(values[0] ?? 0, Math.max(ordinaryCount - 1, selectedIndex))
          );
        }}
        value={[selectedIndex]}
      >
        <span className={styles.track} style={trackStyle}>
          <span aria-hidden className={styles.range} style={selectedStyle} />
          <span aria-hidden className={styles.tickRail}>
            {options.slice(0, ordinaryCount).map((option, index) => {
              const tickStyle: SliderStyle = {
                "--discrete-position": position(index, lastIndex),
              };

              return (
                <span
                  className={styles.tick}
                  data-locked={option.isLocked}
                  data-selected={index <= selectedIndex}
                  key={option.id}
                  style={tickStyle}
                >
                  {option.isLocked === true && !disabled ? (
                    <NamedIcon aria-hidden name="lock" />
                  ) : null}
                </span>
              );
            })}
          </span>
        </span>
        {options.slice(ordinaryCount).map((option, index) => {
          const optionStyle: SliderStyle = {
            "--discrete-position": position(ordinaryCount + index, lastIndex),
          };

          return (
            <button
              aria-label={option.label}
              aria-pressed={selectedOptionId === option.id}
              className={cn(styles.thumbScale, styles.explicitOption)}
              data-selected={selectedOptionId === option.id}
              disabled={disabled || options.length <= 1}
              key={option.id}
              onClick={(event) => {
                event.stopPropagation();
                select(ordinaryCount + index);
              }}
              onPointerDown={(event) => {
                event.preventDefault();
                event.stopPropagation();
              }}
              style={optionStyle}
              type="button"
            >
              <span className={styles.thumb}>{option.icon}</span>
            </button>
          );
        })}
        <span aria-hidden className={styles.visualThumbRail}>
          <span className={styles.thumbScale} style={selectedStyle}>
            <span className={styles.thumb}>
              {selected?.isLocked === true ||
              (disabled &&
                options.some((option) => option.isLocked === true)) ? (
                <NamedIcon aria-hidden name="lock" />
              ) : (
                selected?.icon
              )}
            </span>
          </span>
        </span>
        <SliderThumb
          aria-label={ariaLabel}
          aria-valuetext={selected?.label}
          className={styles.thumbInput}
        />
      </SliderRoot>
    </div>
  );
}

export { DiscreteSlider };

export type { DiscreteSliderOption, DiscreteSliderProps };
